INSERT INTO public.questions (topic_id,difficulty,context_md,statement_md,alternatives,answer_key,explanation_md,hints,status,source,license,origin,numeric_check,review_note)
SELECT t.id,1200,'A prefeitura anunciou um novo estacionamento no centro. No mesmo mês, a única praça do bairro foi cercada para abrigar mais veículos. Em uma crônica, um morador escreveu: ''A cidade ganhou vagas, mas perdeu encontros.''','O contraste da crônica critica principalmente','[{"key":"A","text":"a falta de veículos para circular pelo bairro."},{"key":"B","text":"a construção de prédios residenciais no centro."},{"key":"C","text":"a prioridade dada aos automóveis em prejuízo dos espaços de convivência."},{"key":"D","text":"o excesso de festas que aconteciam na praça."},{"key":"E","text":"a impossibilidade de estacionar em ruas periféricas."}]'::jsonb,'C','A oposição entre ''vagas'' e ''encontros'' mostra a troca de espaço público de convivência por estacionamento. A crítica é à prioridade do automóvel.','["Qual palavra sugere convívio humano?"]'::jsonb,'validated'::public.question_status,'sprint-enem2026-20261103-L01','Original StudyMoon','curated',false,'Questão inédita de revisão ENEM 2026, com gabarito e justificativa conferidos.'
FROM public.topics t WHERE t.slug='lc-interpretacao' AND NOT EXISTS(SELECT 1 FROM public.questions q WHERE q.source='sprint-enem2026-20261103-L01');
INSERT INTO public.questions (topic_id,difficulty,context_md,statement_md,alternatives,answer_key,explanation_md,hints,status,source,license,origin,numeric_check,review_note)
SELECT t.id,1200,'Um boletim comunitário informou: ''O encontro começou às 8h e reuniu 34 pessoas. Para muitos participantes, foi a atividade mais interessante do semestre.''','Qual trecho expressa avaliação subjetiva, e não um dado verificável?','[{"key":"A","text":"''começou às 8h''"},{"key":"B","text":"''a atividade mais interessante do semestre''"},{"key":"C","text":"''reuniu 34 pessoas''"},{"key":"D","text":"''um boletim comunitário informou''"},{"key":"E","text":"''o encontro começou''"}]'::jsonb,'B','''Mais interessante'' é um julgamento de valor. Horário e número de participantes são informações que podem ser verificadas por registros.','["Procure a expressão que depende da opinião de alguém."]'::jsonb,'validated'::public.question_status,'sprint-enem2026-20261103-L02','Original StudyMoon','curated',false,'Questão inédita de revisão ENEM 2026, com gabarito e justificativa conferidos.'
FROM public.topics t WHERE t.slug='lc-interpretacao' AND NOT EXISTS(SELECT 1 FROM public.questions q WHERE q.source='sprint-enem2026-20261103-L02');
INSERT INTO public.questions (topic_id,difficulty,context_md,statement_md,alternatives,answer_key,explanation_md,hints,status,source,license,origin,numeric_check,review_note)
SELECT t.id,1200,'Uma campanha ambiental exibe a frase: ''Leve sua garrafa reutilizável. Faça parte da mudança!''','A função da linguagem predominante nesse anúncio é a','[{"key":"A","text":"metalinguística, por analisar o significado das palavras."},{"key":"B","text":"poética, por valorizar somente a sonoridade."},{"key":"C","text":"referencial, por apresentar dados estatísticos."},{"key":"D","text":"conativa, por buscar influenciar o comportamento do leitor."},{"key":"E","text":"emotiva, por relatar sentimentos íntimos do autor."}]'::jsonb,'D','Os verbos no imperativo (''leve'', ''faça'') dirigem-se ao receptor e incentivam uma ação. Predomina a função conativa ou apelativa.','["O texto tenta informar apenas ou convencer o leitor a agir?"]'::jsonb,'validated'::public.question_status,'sprint-enem2026-20261103-L03','Original StudyMoon','curated',false,'Questão inédita de revisão ENEM 2026, com gabarito e justificativa conferidos.'
FROM public.topics t WHERE t.slug='lc-funcoes-linguagem' AND NOT EXISTS(SELECT 1 FROM public.questions q WHERE q.source='sprint-enem2026-20261103-L03');
INSERT INTO public.questions (topic_id,difficulty,context_md,statement_md,alternatives,answer_key,explanation_md,hints,status,source,license,origin,numeric_check,review_note)
SELECT t.id,1200,'Durante uma ligação com ruído, uma estudante diz: ''Alô, está me ouvindo? Um, dois, três... agora melhorou?''','A função da linguagem em destaque é','[{"key":"A","text":"fática, pois verifica se o canal de comunicação funciona."},{"key":"B","text":"poética, pois explora imagens e metáforas."},{"key":"C","text":"metalinguística, pois define regras gramaticais."},{"key":"D","text":"referencial, pois descreve um fenômeno científico."},{"key":"E","text":"emotiva, pois manifesta tristeza."}]'::jsonb,'A','A função fática aparece em expressões que iniciam, mantêm ou verificam o contato entre interlocutores, como ''alô'' e ''está me ouvindo?''.','["Pense no objetivo de testar a conexão."]'::jsonb,'validated'::public.question_status,'sprint-enem2026-20261103-L04','Original StudyMoon','curated',false,'Questão inédita de revisão ENEM 2026, com gabarito e justificativa conferidos.'
FROM public.topics t WHERE t.slug='lc-funcoes-linguagem' AND NOT EXISTS(SELECT 1 FROM public.questions q WHERE q.source='sprint-enem2026-20261103-L04');
INSERT INTO public.questions (topic_id,difficulty,context_md,statement_md,alternatives,answer_key,explanation_md,hints,status,source,license,origin,numeric_check,review_note)
SELECT t.id,1200,'Em um poema autoral sobre o crescimento urbano, lê-se: ''A cidade devorou a última árvore da avenida.''','A figura de linguagem que atribui à cidade a ação humana de devorar é','[{"key":"A","text":"eufemismo."},{"key":"B","text":"antítese."},{"key":"C","text":"comparação explícita."},{"key":"D","text":"metonímia."},{"key":"E","text":"personificação (prosopopeia)."}]'::jsonb,'E','A cidade, entidade não humana, recebe a ação de ''devorar''. Isso caracteriza personificação, criando uma imagem crítica da urbanização.','["Uma cidade pode literalmente devorar alguma coisa?"]'::jsonb,'validated'::public.question_status,'sprint-enem2026-20261103-L05','Original StudyMoon','curated',false,'Questão inédita de revisão ENEM 2026, com gabarito e justificativa conferidos.'
FROM public.topics t WHERE t.slug='lc-figuras-linguagem' AND NOT EXISTS(SELECT 1 FROM public.questions q WHERE q.source='sprint-enem2026-20261103-L05');
INSERT INTO public.questions (topic_id,difficulty,context_md,statement_md,alternatives,answer_key,explanation_md,hints,status,source,license,origin,numeric_check,review_note)
SELECT t.id,1200,'Após uma longa demora no transporte, um passageiro comenta: ''Esperei um século por esse ônibus!''','O exagero intencional da expressão caracteriza','[{"key":"A","text":"pleonasmo."},{"key":"B","text":"hipérbole."},{"key":"C","text":"ironia."},{"key":"D","text":"sinestesia."},{"key":"E","text":"onomatopeia."}]'::jsonb,'B','''Um século'' amplia exageradamente a duração da espera para transmitir impaciência: é hipérbole, não uma medida literal.','["A duração informada deve ser tomada ao pé da letra?"]'::jsonb,'validated'::public.question_status,'sprint-enem2026-20261103-L06','Original StudyMoon','curated',false,'Questão inédita de revisão ENEM 2026, com gabarito e justificativa conferidos.'
FROM public.topics t WHERE t.slug='lc-figuras-linguagem' AND NOT EXISTS(SELECT 1 FROM public.questions q WHERE q.source='sprint-enem2026-20261103-L06');
INSERT INTO public.questions (topic_id,difficulty,context_md,statement_md,alternatives,answer_key,explanation_md,hints,status,source,license,origin,numeric_check,review_note)
SELECT t.id,1200,'Em uma conversa informal, uma moradora diz: ''Nóis vai cedo pra feira.'' Em um relatório oficial, a mesma pessoa escreve: ''Nós iremos cedo à feira.''','A mudança entre as duas formas exemplifica','[{"key":"A","text":"a incapacidade de falar português corretamente em qualquer situação."},{"key":"B","text":"uma língua sem regras, usada apenas na oralidade."},{"key":"C","text":"a variação linguística e a adequação do registro à situação comunicativa."},{"key":"D","text":"a superioridade intelectual de quem usa a norma-padrão."},{"key":"E","text":"a eliminação das diferenças regionais da língua."}]'::jsonb,'C','Falantes ajustam registros conforme interlocutor e contexto. A norma-padrão tem usos formais, mas variedades populares possuem regularidades e identidade social; não indicam inferioridade.','["Observe que a situação comunicativa mudou."]'::jsonb,'validated'::public.question_status,'sprint-enem2026-20261103-L07','Original StudyMoon','curated',false,'Questão inédita de revisão ENEM 2026, com gabarito e justificativa conferidos.'
FROM public.topics t WHERE t.slug='lc-variacao-linguistica' AND NOT EXISTS(SELECT 1 FROM public.questions q WHERE q.source='sprint-enem2026-20261103-L07');
INSERT INTO public.questions (topic_id,difficulty,context_md,statement_md,alternatives,answer_key,explanation_md,hints,status,source,license,origin,numeric_check,review_note)
SELECT t.id,1200,'A feira literária ocorreu ao ar livre. Embora tenha chovido durante a manhã, os visitantes permaneceram no local.','A palavra ''embora'' estabelece uma relação de','[{"key":"A","text":"concessão, porque apresenta um obstáculo que não impediu o acontecimento."},{"key":"B","text":"causa, pois a chuva produziu a permanência dos visitantes."},{"key":"C","text":"finalidade, pois os visitantes queriam provocar chuva."},{"key":"D","text":"condição obrigatória, pois só haveria feira se chovesse."},{"key":"E","text":"conclusão, pois encerra o raciocínio anterior."}]'::jsonb,'A','A oração concessiva indica um fato contrário à expectativa: mesmo com chuva, os visitantes permaneceram. ''Embora'' é uma conjunção concessiva.','["A chuva impediu ou não a permanência?"]'::jsonb,'validated'::public.question_status,'sprint-enem2026-20261103-L08','Original StudyMoon','curated',false,'Questão inédita de revisão ENEM 2026, com gabarito e justificativa conferidos.'
FROM public.topics t WHERE t.slug='lc-gramatica-aplicada' AND NOT EXISTS(SELECT 1 FROM public.questions q WHERE q.source='sprint-enem2026-20261103-L08');
INSERT INTO public.questions (topic_id,difficulty,context_md,statement_md,alternatives,answer_key,explanation_md,hints,status,source,license,origin,numeric_check,review_note)
SELECT t.id,1200,'Em um caderno de cozinha: ''Misture os ingredientes, aqueça o forno a 180 °C e asse por aproximadamente 25 minutos.''','O texto apresenta traços típicos do gênero','[{"key":"A","text":"notícia, com relato de fato recente."},{"key":"B","text":"crônica, com narrativa subjetiva de um dia."},{"key":"C","text":"entrevista, com turnos de perguntas e respostas."},{"key":"D","text":"receita, com sequência de instruções práticas."},{"key":"E","text":"editorial, com defesa de posicionamento institucional."}]'::jsonb,'D','A sequência de ações expressas no imperativo (''misture'', ''aqueça'', ''asse'') orienta a execução de um procedimento, característica de receita culinária.','["A finalidade é narrar ou ensinar a executar uma tarefa?"]'::jsonb,'validated'::public.question_status,'sprint-enem2026-20261103-L09','Original StudyMoon','curated',false,'Questão inédita de revisão ENEM 2026, com gabarito e justificativa conferidos.'
FROM public.topics t WHERE t.slug='lc-generos-tipos' AND NOT EXISTS(SELECT 1 FROM public.questions q WHERE q.source='sprint-enem2026-20261103-L09');
INSERT INTO public.questions (topic_id,difficulty,context_md,statement_md,alternatives,answer_key,explanation_md,hints,status,source,license,origin,numeric_check,review_note)
SELECT t.id,1200,'Um leitor envia ao jornal local: ''Senhora editora, a reportagem sobre a coleta seletiva foi importante, mas deixou de ouvir os catadores que atuam em nosso bairro.''','O objetivo predominante desse texto é','[{"key":"A","text":"registrar uma ordem administrativa obrigatória."},{"key":"B","text":"descrever um experimento científico."},{"key":"C","text":"divulgar o cardápio de uma instituição."},{"key":"D","text":"apresentar instruções de descarte em etapas."},{"key":"E","text":"manifestar uma avaliação crítica sobre conteúdo publicado."}]'::jsonb,'E','A carta de leitor permite comentar, concordar, questionar ou criticar matérias. Aqui, o emissor avalia a reportagem e aponta a ausência de vozes relevantes.','["A pessoa está comentando uma matéria que leu."]'::jsonb,'validated'::public.question_status,'sprint-enem2026-20261103-L10','Original StudyMoon','curated',false,'Questão inédita de revisão ENEM 2026, com gabarito e justificativa conferidos.'
FROM public.topics t WHERE t.slug='lc-generos-tipos' AND NOT EXISTS(SELECT 1 FROM public.questions q WHERE q.source='sprint-enem2026-20261103-L10');
INSERT INTO public.questions (topic_id,difficulty,context_md,statement_md,alternatives,answer_key,explanation_md,hints,status,source,license,origin,numeric_check,review_note)
SELECT t.id,1200,'Aviso em inglês numa escola: ''Bring your reusable bottle. Free drinking-water refill stations are available on every floor.''','A orientação central do aviso é que os estudantes','[{"key":"A","text":"comprem garrafas de água em cada andar."},{"key":"B","text":"levem uma garrafa reutilizável que pode ser reabastecida gratuitamente."},{"key":"C","text":"evitem consumir água durante as aulas."},{"key":"D","text":"utilizem apenas copos descartáveis."},{"key":"E","text":"paguem uma taxa para usar bebedouros."}]'::jsonb,'B','''Bring your reusable bottle'' significa levar a própria garrafa reutilizável; ''free refill stations'' são pontos gratuitos para reabastecê-la.','["Reusable = reutilizável; refill = reabastecimento."]'::jsonb,'validated'::public.question_status,'sprint-enem2026-20261103-L11','Original StudyMoon','curated',false,'Questão inédita de revisão ENEM 2026, com gabarito e justificativa conferidos.'
FROM public.topics t WHERE t.slug='lc-lingua-estrangeira' AND NOT EXISTS(SELECT 1 FROM public.questions q WHERE q.source='sprint-enem2026-20261103-L11');
INSERT INTO public.questions (topic_id,difficulty,context_md,statement_md,alternatives,answer_key,explanation_md,hints,status,source,license,origin,numeric_check,review_note)
SELECT t.id,1200,'Placa em uma biblioteca: ''This is a quiet study area. Please take group conversations outside.''','A regra expressa na placa solicita que as pessoas','[{"key":"A","text":"façam apresentações em grupo dentro da biblioteca."},{"key":"B","text":"evitem estudar individualmente no local."},{"key":"C","text":"realizem conversas em grupo fora da área silenciosa."},{"key":"D","text":"desliguem a iluminação para estudar."},{"key":"E","text":"deixem seus livros do lado de fora."}]'::jsonb,'C','''Quiet study area'' indica ambiente silencioso e ''take group conversations outside'' pede que conversas em grupo aconteçam fora da área.','["Outside significa ''do lado de fora''."]'::jsonb,'validated'::public.question_status,'sprint-enem2026-20261103-L12','Original StudyMoon','curated',false,'Questão inédita de revisão ENEM 2026, com gabarito e justificativa conferidos.'
FROM public.topics t WHERE t.slug='lc-lingua-estrangeira' AND NOT EXISTS(SELECT 1 FROM public.questions q WHERE q.source='sprint-enem2026-20261103-L12');
INSERT INTO public.questions (topic_id,difficulty,context_md,statement_md,alternatives,answer_key,explanation_md,hints,status,source,license,origin,numeric_check,review_note)
SELECT t.id,1200,'Um poeta do início do século XX emprega versos livres, linguagem cotidiana e humor para retratar a vida na rua, rompendo com formas rígidas da poesia tradicional.','Essas escolhas aproximam o texto de uma proposta característica do','[{"key":"A","text":"Modernismo, que buscava renovar a expressão artística e aproximá-la do cotidiano."},{"key":"B","text":"Arcadismo, que defendia o retorno exclusivo à mitologia clássica."},{"key":"C","text":"Parnasianismo, definido pela rejeição total do trabalho formal."},{"key":"D","text":"Barroco, marcado apenas por linguagem jornalística."},{"key":"E","text":"Trovadorismo, dedicado ao registro de notícias urbanas."}]'::jsonb,'A','O Modernismo brasileiro valorizou a experimentação estética, a linguagem próxima da fala e a revisão de modelos artísticos acadêmicos, especialmente a partir de 1922.','["Pense no movimento que questionou padrões artísticos acadêmicos."]'::jsonb,'validated'::public.question_status,'sprint-enem2026-20261103-L13','Original StudyMoon','curated',false,'Questão inédita de revisão ENEM 2026, com gabarito e justificativa conferidos.'
FROM public.topics t WHERE t.slug='lc-literatura-movimentos' AND NOT EXISTS(SELECT 1 FROM public.questions q WHERE q.source='sprint-enem2026-20261103-L13');
INSERT INTO public.questions (topic_id,difficulty,context_md,statement_md,alternatives,answer_key,explanation_md,hints,status,source,license,origin,numeric_check,review_note)
SELECT t.id,1200,'Em um romance, o narrador revela que a imagem de honestidade de certo comerciante encobre interesses econômicos e atitudes contraditórias. O texto observa comportamentos e relações sociais com olhar crítico.','O procedimento literário é associado principalmente à tendência','[{"key":"A","text":"romântica de idealização absoluta do protagonista."},{"key":"B","text":"épica de exaltação de heróis lendários."},{"key":"C","text":"simbolista de rejeição a qualquer observação social."},{"key":"D","text":"árcade de fuga integral para a paisagem pastoril."},{"key":"E","text":"realista de análise crítica e psicológica da sociedade."}]'::jsonb,'E','O Realismo examina contradições humanas e relações sociais, frequentemente desmontando idealizações e revelando motivações psicológicas ou econômicas.','["O narrador idealiza ou questiona as aparências?"]'::jsonb,'validated'::public.question_status,'sprint-enem2026-20261103-L14','Original StudyMoon','curated',false,'Questão inédita de revisão ENEM 2026, com gabarito e justificativa conferidos.'
FROM public.topics t WHERE t.slug='lc-literatura-movimentos' AND NOT EXISTS(SELECT 1 FROM public.questions q WHERE q.source='sprint-enem2026-20261103-L14');
INSERT INTO public.questions (topic_id,difficulty,context_md,statement_md,alternatives,answer_key,explanation_md,hints,status,source,license,origin,numeric_check,review_note)
SELECT t.id,1200,'Uma rede social passa a recomendar a uma pessoa quase exclusivamente vídeos e opiniões semelhantes aos que ela já costuma aprovar. Com o tempo, ela raramente encontra perspectivas divergentes.','Um possível efeito social desse mecanismo é','[{"key":"A","text":"a garantia de que todas as notícias sejam verificadas."},{"key":"B","text":"o desaparecimento das preferências individuais."},{"key":"C","text":"a divulgação equilibrada de qualquer ponto de vista."},{"key":"D","text":"o reforço de bolhas informacionais e a redução da diversidade de opiniões recebidas."},{"key":"E","text":"o impedimento técnico de qualquer desinformação."}]'::jsonb,'D','Sistemas de recomendação podem reforçar conteúdos semelhantes aos já consumidos, criando bolhas informacionais que limitam o contato com perspectivas diferentes.','["O que acontece quando só aparecem ideias parecidas?"]'::jsonb,'validated'::public.question_status,'sprint-enem2026-20261103-L15','Original StudyMoon','curated',false,'Questão inédita de revisão ENEM 2026, com gabarito e justificativa conferidos.'
FROM public.topics t WHERE t.slug='lc-tecnologias-comunicacao' AND NOT EXISTS(SELECT 1 FROM public.questions q WHERE q.source='sprint-enem2026-20261103-L15');
INSERT INTO public.questions (topic_id,difficulty,context_md,statement_md,alternatives,answer_key,explanation_md,hints,status,source,license,origin,numeric_check,review_note)
SELECT t.id,1200,'Uma escola ampliou o horário de funcionamento da biblioteca. Portanto, os alunos passaram a ter mais oportunidades de estudo no contraturno.','Nesse contexto, o conectivo ''portanto'' expressa','[{"key":"A","text":"alternância entre duas possibilidades."},{"key":"B","text":"conclusão ou consequência em relação à informação anterior."},{"key":"C","text":"comparação de igualdade."},{"key":"D","text":"oposição entre ideias incompatíveis."},{"key":"E","text":"dúvida quanto à informação apresentada."}]'::jsonb,'B','''Portanto'' introduz uma conclusão ou resultado derivado da ampliação do horário, articulando a relação lógica entre as frases.','["A segunda frase decorre da primeira."]'::jsonb,'validated'::public.question_status,'sprint-enem2026-20261103-L16','Original StudyMoon','curated',false,'Questão inédita de revisão ENEM 2026, com gabarito e justificativa conferidos.'
FROM public.topics t WHERE t.slug='lc-gramatica-aplicada' AND NOT EXISTS(SELECT 1 FROM public.questions q WHERE q.source='sprint-enem2026-20261103-L16');
